// Sahayog Ticket Dashboard Script
(function () {
  // Safely resolve root element (ShadowRoot or Document)
  let root = null;
  try {
    if (typeof root_element !== "undefined" && root_element && root_element && typeof root_element.querySelector === "function") {
      root = root_element;
    }
  } catch (e) {}

  if (!root) {
    try {
      const customBlocks = document.querySelectorAll("[class*='custom-block-widget-box'] > *");
      for (let i = 0; i < customBlocks.length; i++) {
        if (customBlocks[i].shadowRoot && customBlocks[i].shadowRoot.querySelector(".st-app")) {
          root = customBlocks[i].shadowRoot;
          break;
        }
      }
    } catch (e) {}
  }

  if (!root || typeof root.querySelector !== "function") {
    root = document;
  }

  // Global state
  const state = {
    status: "",
    search: "",
    page: 1,
    pageSize: 10,
    total: 0,
    searchDebounce: null,
  };

  const STATUS_META = [
    { key: "open", status: "Open", count: "count-open" },
    { key: "in_progress", status: "In-Progress", count: "count-inprogress" },
    { key: "resolved", status: "Resolved", count: "count-resolved" },
    { key: "closed", status: "Closed", count: "count-closed" },
  ];

  const isAdmin = frappe.session.user === "Administrator";

  // Greeting
  const empNameEl = root.querySelector("#emp-name");
  if (empNameEl) {
    if (isAdmin) {
      empNameEl.textContent = "Hello, Administrator";
    } else {
      frappe.call({
        method: "frappe.client.get_value",
        args: {
          doctype: "User",
          filters: { name: frappe.session.user },
          fieldname: ["first_name", "last_name"],
        },
        callback(r) {
          if (r.message) {
            const { first_name, last_name } = r.message;
            empNameEl.textContent = `Hello, ${[first_name, last_name].filter(Boolean).join(" ")}`;
          }
        },
      });
    }
  }

  function ownerFilter() {
    if (isAdmin) return {};
    const empuser = frappe.session.user;
    const match = empuser.match(/\d+/);
    return { employee_id: match ? match[0] : empuser };
  }

  function loadCounts() {
    frappe.call({
      method: "sahayog_ticket.sahayog_ticket.doctype.sahayog_ticket.sahayog_ticket.get_counts",
      args: ownerFilter(),
      callback(response) {
        const counts = response.message || {};
        let total = 0;
        STATUS_META.forEach(({ key, count }) => {
          const value = counts[key] || 0;
          total += value;
          const el = root.querySelector("#" + count);
          if (el) el.textContent = value;
        });
        const allEl = root.querySelector("#count-all");
        if (allEl) allEl.textContent = total;

        // Sticky mobile bottom navigation badges
        const bnavCounts = {
          "bnav-count-all": total,
          "bnav-count-open": counts.open || 0,
          "bnav-count-in_progress": counts.in_progress || 0,
          "bnav-count-resolved": counts.resolved || 0,
          "bnav-count-closed": counts.closed || 0,
        };

        Object.entries(bnavCounts).forEach(([id, val]) => {
          const badge = root.querySelector("#" + id);
          if (badge) {
            const num = parseInt(val, 10) || 0;
            badge.textContent = num;
            if (num > 0) {
              badge.style.setProperty("display", "inline-flex", "important");
            } else {
              badge.style.setProperty("display", "none", "important");
            }
          }
        });
      },
    });
  }

  function setActiveChip(status) {
    root.querySelectorAll(".st-chip").forEach((chip) => {
      chip.classList.toggle("is-active", (chip.dataset.status || "") === status);
    });
    root.querySelectorAll(".st-bnav-item").forEach((item) => {
      item.classList.toggle("is-active", (item.dataset.status || "") === status);
    });
  }

  root.querySelectorAll(".st-chip, .st-bnav-item").forEach((btn) => {
    btn.addEventListener("click", () => {
      state.status = btn.dataset.status || "";
      state.page = 1;
      setActiveChip(state.status);
      loadTickets();
    });
  });

  // ---------- Toolbar: search + page size ----------
  const searchInput = root.querySelector("#stSearchInput");
  if (searchInput) {
    searchInput.addEventListener("input", () => {
      clearTimeout(state.searchDebounce);
      state.searchDebounce = setTimeout(() => {
        state.search = searchInput.value.trim();
        state.page = 1;
        loadTickets();
      }, 350);
    });
  }

  const pageSizeSelect = root.querySelector("#stPageSize");
  if (pageSizeSelect) {
    pageSizeSelect.addEventListener("change", () => {
      state.pageSize = parseInt(pageSizeSelect.value, 10) || 10;
      state.page = 1;
      loadTickets();
    });
  }

  // ---------- Pagination controls ----------
  const prevBtn = root.querySelector("#stPrevPage");
  const nextBtn = root.querySelector("#stNextPage");
  const pageIndicator = root.querySelector("#stPageIndicator");
  const paginationInfo = root.querySelector("#stPaginationInfo");

  if (prevBtn) {
    prevBtn.addEventListener("click", () => {
      if (state.page > 1) {
        state.page -= 1;
        loadTickets();
      }
    });
  }

  if (nextBtn) {
    nextBtn.addEventListener("click", () => {
      const maxPage = Math.max(1, Math.ceil(state.total / state.pageSize));
      if (state.page < maxPage) {
        state.page += 1;
        loadTickets();
      }
    });
  }

  function updatePaginationUI() {
    const maxPage = Math.max(1, Math.ceil(state.total / state.pageSize));
    if (pageIndicator) pageIndicator.textContent = `Page ${state.page} of ${maxPage}`;
    if (prevBtn) prevBtn.disabled = state.page <= 1;
    if (nextBtn) nextBtn.disabled = state.page >= maxPage;

    if (paginationInfo) {
      if (state.total === 0) {
        paginationInfo.textContent = "0 tickets";
      } else {
        const start = (state.page - 1) * state.pageSize + 1;
        const end = Math.min(state.page * state.pageSize, state.total);
        paginationInfo.textContent = `${start}–${end} of ${state.total} tickets`;
      }
    }
  }

  // ---------- Table rendering ----------
  const tableBody = root.querySelector("#stTableBody");
  const loadingEl = root.querySelector("#stLoading");
  const emptyEl = root.querySelector("#stEmpty");

  function statusDotClass(status) {
    const map = {
      "Open": "st-dot-open",
      "In-Progress": "st-dot-inprogress",
      "Resolved": "st-dot-resolved",
      "Closed": "st-dot-closed",
    };
    return map[status] || "st-dot-all";
  }

  function formatDate(value) {
    if (!value) return "—";
    const d = new Date(value);
    if (isNaN(d.getTime())) return value;
    const dd = String(d.getDate()).padStart(2, "0");
    const mm = String(d.getMonth() + 1).padStart(2, "0");
    const yyyy = d.getFullYear();
    return `${dd}-${mm}-${yyyy}`;
  }

  function formatAge(value) {
    if (!value) return "—";
    const created = new Date(value);
    if (isNaN(created.getTime())) return "—";
    const startOfDay = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate());
    const days = Math.round((startOfDay(new Date()) - startOfDay(created)) / (1000 * 60 * 60 * 24));
    if (days <= 0) return "Today";
    if (days === 1) return "1 Day";
    return `${days} Days`;
  }

  // Relative humanized pretty date for Last Updated column
  function formatPrettyDate(value) {
    if (!value) return "—";
    try {
      if (typeof comment_when === "function") {
        return comment_when(value);
      }
      if (window.frappe && frappe.datetime && typeof frappe.datetime.comment_when === "function") {
        return frappe.datetime.comment_when(value);
      }
      if (window.frappe && frappe.datetime && typeof frappe.datetime.prettyDate === "function") {
        return frappe.datetime.prettyDate(value);
      }
    } catch (e) {}

    try {
      const d = new Date(typeof value === "string" ? value.replace(/-/g, "/").replace("T", " ") : value);
      if (isNaN(d.getTime())) return value;
      const diff = Math.floor((Date.now() - d.getTime()) / 1000);
      if (diff < 60) return "just now";
      if (diff < 3600) return `${Math.floor(diff / 60)} minutes ago`;
      if (diff < 86400) return `${Math.floor(diff / 3600)} hours ago`;
      const days = Math.floor(diff / 86400);
      if (days === 1) return "yesterday";
      if (days < 7) return `${days} days ago`;
      return formatDate(value);
    } catch (err) {
      return formatDate(value);
    }
  }

  // Pure text time ago for notifications (never returns raw HTML spans)
  function getSimpleTimeAgo(value) {
    if (!value) return "recently";
    try {
      if (window.frappe && frappe.datetime && typeof frappe.datetime.prettyDate === "function") {
        const pd = frappe.datetime.prettyDate(value);
        if (pd && typeof pd === "string" && !pd.includes("<")) return pd;
      }
    } catch (e) {}

    try {
      const d = new Date(typeof value === "string" ? value.replace(/-/g, "/").replace("T", " ") : value);
      if (isNaN(d.getTime())) return "recently";
      const diff = Math.floor((Date.now() - d.getTime()) / 1000);
      if (diff < 60) return "just now";
      if (diff < 3600) return Math.floor(diff / 60) + "m ago";
      if (diff < 86400) return Math.floor(diff / 3600) + "h ago";
      const days = Math.floor(diff / 86400);
      if (days === 1) return "yesterday";
      if (days < 7) return days + "d ago";
      return formatDate(value);
    } catch (err) {
      return "recently";
    }
  }

  function renderRows(rows) {
    if (!tableBody) return;
    tableBody.innerHTML = "";
    rows.forEach((row) => {
      const tr = document.createElement("tr");
      tr.innerHTML = `
        <td class="st-ticket-id" data-label="Ticket">${frappe.utils.escape_html(row.name)}</td>
        <td class="st-subject-cell" data-label="Subject">${frappe.utils.escape_html(row.ticket_type || "—")}</td>
        <td data-label="Status">
          <span class="st-badge">
            <span class="st-chip-dot ${statusDotClass(row.status)}"></span>
            ${frappe.utils.escape_html(row.status || "—")}
          </span>
        </td>
        <td class="st-date-cell" data-label="Created">
          <span class="st-date-main">${formatDate(row.creation)}</span>
        </td>
        <td class="st-age-cell" data-label="Age (Days)">${formatAge(row.creation)}</td>
        <td class="st-date-cell" data-label="Last Updated">
          <span class="st-date-main">${formatPrettyDate(row.modified)}</span>
        </td>
      `;
      tr.addEventListener("click", () => {
        window.location.href = `/app/sahayog-ticket/${encodeURIComponent(row.name)}`;
      });
      tableBody.appendChild(tr);
    });
  }

  function buildFilters() {
    const filters = {};
    if (!isAdmin) filters.owner = frappe.session.user;
    if (state.status) filters.status = state.status;
    return filters;
  }

  function loadTickets() {
    if (loadingEl) loadingEl.style.display = "block";
    if (emptyEl) emptyEl.style.display = "none";
    if (tableBody) tableBody.innerHTML = "";

    const filters = buildFilters();
    const or_filters = state.search
      ? [
          ["Sahayog Ticket", "name", "like", `%${state.search}%`],
          ["Sahayog Ticket", "ticket_type", "like", `%${state.search}%`],
        ]
      : undefined;

    frappe.call({
      method: "frappe.client.get_count",
      args: { doctype: "Sahayog Ticket", filters, or_filters },
      callback(countResponse) {
        state.total = countResponse.message || 0;

        frappe.call({
          method: "frappe.client.get_list",
          args: {
            doctype: "Sahayog Ticket",
            fields: ["name", "ticket_type", "status", "creation", "modified"],
            filters,
            or_filters,
            order_by: "modified desc",
            limit_start: (state.page - 1) * state.pageSize,
            limit_page_length: state.pageSize,
          },
          callback(listResponse) {
            if (loadingEl) loadingEl.style.display = "none";
            const rows = listResponse.message || [];
            if (rows.length === 0) {
              if (emptyEl) emptyEl.style.display = "block";
            } else {
              renderRows(rows);
            }
            updatePaginationUI();
          },
        });
      },
    });
  }

  // ---------- Notification Dropdown & Comments Controller ----------
  const notifWrapper = root.querySelector("#stNotifWrapper");
  const notifBtn = root.querySelector("#stNotifBtn");
  const notifBadge = root.querySelector("#stNotifBadge");
  const notifDropdown = root.querySelector("#stNotifDropdown");
  const notifDdCount = root.querySelector("#stNotifDdCount");
  const notifRefresh = root.querySelector("#stNotifRefresh");
  const notifDdLoading = root.querySelector("#stNotifDdLoading");
  const notifDdEmpty = root.querySelector("#stNotifDdEmpty");
  const notifDdList = root.querySelector("#stNotifDdList");

  let isDropdownOpen = false;

  const notifBackdrop = root.querySelector("#stNotifBackdrop");
  const notifClose = root.querySelector("#stNotifClose");

  function positionMobileDropdown() {
    if (window.innerWidth <= 768 && notifDropdown) {
      const stickyEl = root.querySelector(".st-sticky-header");
      if (stickyEl) {
        const rect = stickyEl.getBoundingClientRect();
        const topOffset = Math.max(120, Math.round(rect.bottom) + 6);
        notifDropdown.style.setProperty("top", topOffset + "px", "important");
        const maxH = Math.max(200, window.innerHeight - topOffset - 75);
        notifDropdown.style.setProperty("max-height", maxH + "px", "important");
        const bodyEl = root.querySelector("#stNotifDdBody");
        if (bodyEl) {
          bodyEl.style.setProperty("max-height", (maxH - 50) + "px", "important");
        }
      }
    }
  }

  function toggleDropdown() {
    isDropdownOpen = !isDropdownOpen;
    if (notifDropdown) {
      notifDropdown.style.display = isDropdownOpen ? "flex" : "none";
      if (isDropdownOpen) {
        positionMobileDropdown();
      }
    }
    if (notifBackdrop) {
      notifBackdrop.style.display = (isDropdownOpen && window.innerWidth <= 768) ? "block" : "none";
    }
    if (notifBtn) {
      notifBtn.setAttribute("aria-expanded", isDropdownOpen ? "true" : "false");
    }
    if (isDropdownOpen) {
      loadComments();
    }
  }

  function closeDropdown() {
    isDropdownOpen = false;
    if (notifDropdown) {
      notifDropdown.style.display = "none";
    }
    if (notifBackdrop) {
      notifBackdrop.style.display = "none";
    }
    if (notifBtn) {
      notifBtn.setAttribute("aria-expanded", "false");
    }
  }

  if (notifBackdrop) {
    notifBackdrop.addEventListener("click", () => {
      closeDropdown();
    });
  }

  if (notifClose) {
    notifClose.addEventListener("click", () => {
      closeDropdown();
    });
  }

  if (notifBtn) {
    notifBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      toggleDropdown();
    });
  }


  const notifMarkAll = root.querySelector("#stNotifMarkAll");
  if (notifMarkAll) {
    notifMarkAll.addEventListener("click", (e) => {
      e.stopPropagation();
      frappe.call({
        method: "sahayog_ticket.sahayog_ticket.doctype.sahayog_ticket.sahayog_ticket.mark_all_comments_seen",
        callback() {
          if (notifBadge) notifBadge.style.setProperty("display", "none", "important");
          if (notifDdCount) notifDdCount.style.setProperty("display", "none", "important");
          root.querySelectorAll(".st-notif-item.st-notif-unread").forEach((el) => {
            el.classList.remove("st-notif-unread");
            el.classList.add("st-notif-read");
            const dot = el.querySelector(".st-notif-unread-dot");
            if (dot) dot.remove();
          });
        }
      });
    });
  }

  if (notifRefresh) {
    notifRefresh.addEventListener("click", (e) => {
      e.stopPropagation();
      loadComments();
    });
  }

  // Click outside to close dropdown
  document.addEventListener("click", (e) => {
    if (isDropdownOpen && notifWrapper && !notifWrapper.contains(e.target)) {
      closeDropdown();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && isDropdownOpen) {
      closeDropdown();
    }
  });

  function stripHtml(html) {
    if (!html) return "";
    const tmp = document.createElement("div");
    tmp.innerHTML = html;
    return (tmp.textContent || tmp.innerText || "").trim();
  }

  function updateBadgeAndHeader(count) {
    if (notifBadge) {
      if (count > 0) {
        notifBadge.textContent = count > 9 ? "9+" : count;
        notifBadge.style.setProperty("display", "inline-flex", "important");
      } else {
        notifBadge.style.setProperty("display", "none", "important");
      }
    }
    if (notifDdCount) {
      if (count > 0) {
        notifDdCount.textContent = count + " new";
        notifDdCount.style.setProperty("display", "inline-block", "important");
      } else {
        notifDdCount.style.setProperty("display", "none", "important");
      }
    }
    if (notifMarkAll) {
      notifMarkAll.style.display = count > 0 ? "inline-flex" : "none";
    }
  }

  function checkCommentsBadge() {
    frappe.call({
      method: "sahayog_ticket.sahayog_ticket.doctype.sahayog_ticket.sahayog_ticket.get_recent_ticket_comments",
      args: { limit: 20, only_unseen: 1 },
      callback(res) {
        const list = res.message || [];
        updateBadgeAndHeader(list.length);
      }
    });
  }

  function loadComments() {
    if (!notifDdList) return;
    if (notifDdLoading) {
      notifDdLoading.classList.add("st-active");
      notifDdLoading.style.setProperty("display", "flex", "important");
    }
    if (notifDdEmpty) {
      notifDdEmpty.classList.remove("st-active");
      notifDdEmpty.style.setProperty("display", "none", "important");
    }
    notifDdList.innerHTML = "";

    frappe.call({
      method: "sahayog_ticket.sahayog_ticket.doctype.sahayog_ticket.sahayog_ticket.get_recent_ticket_comments",
      args: { limit: 20, only_unseen: 1 },
      callback(res) {
        if (notifDdLoading) {
          notifDdLoading.classList.remove("st-active");
          notifDdLoading.style.setProperty("display", "none", "important");
        }
        const items = res.message || [];
        updateBadgeAndHeader(items.length);

        if (items.length === 0) {
          if (notifDdEmpty) {
            notifDdEmpty.classList.add("st-active");
            notifDdEmpty.style.setProperty("display", "block", "important");
          }
          return;
        }

        items.forEach((c) => {
          const item = document.createElement("div");
          item.className = "st-notif-item st-notif-unread";

          const rawText = stripHtml(c.comment_content) || "No message content";
          const authorName = c.commenter_name || c.commented_by || "User";
          const initial = authorName.charAt(0).toUpperCase() || "U";
          const timeAgo = getSimpleTimeAgo(c.comment_time);

          item.innerHTML = `
            <div class="st-notif-item-top">
              <div class="st-notif-author-wrap">
                <span class="st-notif-avatar">${frappe.utils.escape_html(initial)}</span>
                <span class="st-notif-author-name">${frappe.utils.escape_html(authorName)}</span>
                <span class="st-notif-unread-dot" title="Unread comment"></span>
              </div>
              <span class="st-notif-time">${frappe.utils.escape_html(timeAgo)}</span>
            </div>
            <p class="st-notif-content">${frappe.utils.escape_html(rawText)}</p>
            <div class="st-notif-item-footer">
              <span class="st-notif-ticket-tag">
                <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 9a3 3 0 0 1 0 6v2a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-2a3 3 0 0 1 0-6V7a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2z"/></svg>
                ${frappe.utils.escape_html(c.ticket_name)}
              </span>
              ${c.ticket_type ? `<span class="st-notif-ticket-type">${frappe.utils.escape_html(c.ticket_type)}</span>` : ""}
            </div>
          `;

          // Click on comment: immediately remove from dropdown, mark seen in DB, and navigate
          item.addEventListener("click", () => {
            item.remove();
            const remaining = notifDdList.querySelectorAll(".st-notif-item").length;
            updateBadgeAndHeader(remaining);
            if (remaining === 0 && notifDdEmpty) {
              notifDdEmpty.classList.add("st-active");
              notifDdEmpty.style.setProperty("display", "block", "important");
            }

            frappe.call({
              method: "sahayog_ticket.sahayog_ticket.doctype.sahayog_ticket.sahayog_ticket.mark_comment_as_seen",
              args: { comment_id: c.comment_id },
              always: function() {
                closeDropdown();
                window.location.href = `/app/sahayog-ticket/${encodeURIComponent(c.ticket_name)}`;
              }
            });
          });

          notifDdList.appendChild(item);
        });
      }
    });
  }

  // Read all: mark all seen, clear list immediately, and show empty state
  if (notifMarkAll) {
    notifMarkAll.addEventListener("click", (e) => {
      e.stopPropagation();

      // Clear immediately
      if (notifDdList) notifDdList.innerHTML = "";
      if (notifDdEmpty) {
        notifDdEmpty.classList.add("st-active");
        notifDdEmpty.style.setProperty("display", "block", "important");
      }
      updateBadgeAndHeader(0);

      frappe.call({
        method: "sahayog_ticket.sahayog_ticket.doctype.sahayog_ticket.sahayog_ticket.mark_all_comments_seen",
        callback() {
          frappe.show_alert({
            message: __("All comments marked as read"),
            indicator: "green",
          }, 3);
        }
      });
    });
  }

    if (notifRefresh) {
    notifRefresh.addEventListener("click", (e) => {
      e.stopPropagation();
      loadComments();
    });
  }

  // Click outside to close dropdown
  document.addEventListener("click", (e) => {
    if (isDropdownOpen && notifWrapper && !notifWrapper.contains(e.target)) {
      closeDropdown();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && isDropdownOpen) {
      closeDropdown();
    }
  });

  function stripHtml(html) {
    if (!html) return "";
    const tmp = document.createElement("div");
    tmp.innerHTML = html;
    return (tmp.textContent || tmp.innerText || "").trim();
  }

  // Sticky header offset adjustment for mobile
  function updateStickyOffset() {
    const stickyEl = root.querySelector(".st-sticky-header");
    if (!stickyEl) return;
    if (window.innerWidth <= 768) {
      const pageHead = document.querySelector(".page-head");
      const navbar = document.querySelector(".navbar");
      let offset = 0;
      if (navbar) offset += navbar.offsetHeight;
      if (pageHead && window.getComputedStyle(pageHead).position === "sticky") {
        offset += pageHead.offsetHeight;
      }
      stickyEl.style.top = (offset || 48) + "px";
    } else {
      stickyEl.style.top = "0px";
    }
  }
  window.addEventListener("resize", updateStickyOffset);
  setTimeout(updateStickyOffset, 200);

  // Initialize
  loadCounts();
  loadTickets();
  checkCommentsBadge();
})();

