/* Sahayog Ticket — Custom HTML Block
   Minimal, Frappe v16 (Desk) styled dashboard. Uses Frappe's own CSS variables
   with safe fallbacks so it still looks right if a variable isn't defined. */

.st-app {
  --st-border: var(--border-color, #d1d8dd);
  --st-text: var(--text-color, #1c2126);
  --st-text-muted: var(--text-muted, #8d99a6);
  --st-bg: var(--fg-color, #ffffff);
  --st-bg-subtle: var(--subtle-fg, #f7f8f9);
  --st-primary: #417c7d;
  --st-primary-hover: #346566;
  --st-primary-light: rgba(65, 124, 125, 0.12);
  --st-radius: var(--border-radius-md, 8px);
  --st-shadow: var(--shadow-sm, 0 1px 2px rgba(0, 0, 0, 0.06));

  font-family: var(--font-stack, "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif);
  color: var(--st-text);
  max-width: 1100px;
  margin: 0 auto;
}

.st-app * {
  box-sizing: border-box;
}

/* Sticky Top Section (Header + Chips + Toolbar) */
.st-sticky-header {
  position: sticky;
  top: 0;
  z-index: 15;
  background: var(--st-bg, #ffffff);
  padding-top: 2px;
  padding-bottom: 2px;
  transition: top 0.2s ease;
}

/* Header */
.st-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 4px 0 12px;
  flex-wrap: wrap;
}

.st-header-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.st-logo {
  width: 38px;
  height: 38px;
  object-fit: contain;
  border-radius: 8px;
  background: var(--st-bg-subtle);
  padding: 5px;
  flex-shrink: 0;
}

.st-emp-name {
  margin: 0 0 2px;
  font-size: 12px;
  color: var(--st-text-muted);
}

.st-title {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.st-header-right {
  display: flex;
  align-items: center;
  gap: 10px;
  position: relative;
  flex-shrink: 0;
}

/* Create New Ticket Button - 100% Solid & Visible */
.st-btn-primary {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 6px !important;
  padding: 7px 14px !important;
  background: #417c7d !important;
  color: #ffffff !important;
  font-size: 12.5px !important;
  font-weight: 500 !important;
  border-radius: 8px !important;
  text-decoration: none !important;
  transition: filter 0.15s ease, transform 0.15s ease, background 0.15s ease !important;
  white-space: nowrap !important;
  box-shadow: 0 1px 3px rgba(65, 124, 125, 0.3) !important;
  border: none !important;
  cursor: pointer !important;
}

.st-btn-primary:hover {
  background: #346566 !important;
  color: #ffffff !important;
  transform: translateY(-1px);
}

/* Notification Button */
.st-notif-wrapper {
  position: relative;
  display: inline-flex;
}

.st-notif-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--st-bg, #ffffff);
  border: 1px solid var(--st-border, #cbd5e1);
  color: #417c7d;
  cursor: pointer;
  transition: all 0.15s ease;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
  padding: 0;
}

.st-notif-btn:hover {
  background: rgba(65, 124, 125, 0.08);
  border-color: #417c7d;
  color: #346566;
  transform: scale(1.05);
}

.st-notif-badge {
  position: absolute;
  top: -3px;
  right: -3px;
  min-width: 15px;
  height: 15px;
  padding: 0 4px;
  border-radius: 10px;
  background: #417c7d;
  color: #ffffff;
  font-size: 9.5px;
  font-weight: 700;
  display: none;
  align-items: center;
  justify-content: center;
  line-height: 1;
  border: 1.5px solid var(--st-bg, #ffffff);
  box-shadow: 0 1px 3px rgba(65, 124, 125, 0.4);
}

/* Notification Dropdown Popover Box */
.st-notif-dropdown {
  position: absolute !important;
  top: calc(100% + 8px) !important;
  right: 0 !important;
  width: 350px !important;
  max-width: calc(100vw - 28px) !important;
  max-height: 460px !important;
  display: none;
  flex-direction: column !important;
  background: #ffffff !important;
  border-radius: 12px !important;
  border: 1px solid #cbd5e1 !important;
  box-shadow: 0 16px 36px -4px rgba(0, 0, 0, 0.2), 0 4px 12px rgba(0, 0, 0, 0.08) !important;
  z-index: 9999 !important;
  overflow: hidden !important;
  animation: stDropdownSlide 0.18s cubic-bezier(0.16, 1, 0.3, 1) !important;
}

@keyframes stDropdownSlide {
  from { opacity: 0; transform: translateY(-6px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.st-notif-dd-header {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  padding: 10px 14px !important;
  background: #f8fafc !important;
  border-bottom: 1px solid #e2e8f0 !important;
}

.st-notif-dd-title-wrap {
  display: flex !important;
  align-items: center !important;
  gap: 7px !important;
}

.st-notif-dd-title {
  font-size: 13.5px !important;
  font-weight: 600 !important;
  color: #1e293b !important;
}

.st-notif-dd-badge {
  font-size: 10px !important;
  font-weight: 700 !important;
  padding: 1px 6px !important;
  border-radius: 10px !important;
  background: rgba(65, 124, 125, 0.15) !important;
  color: #417c7d !important;
}

.st-notif-dd-refresh {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 24px !important;
  height: 24px !important;
  border-radius: 4px !important;
  border: none !important;
  background: transparent !important;
  color: #64748b !important;
  cursor: pointer !important;
  transition: all 0.15s ease !important;
}

.st-notif-dd-refresh:hover {
  background: rgba(0, 0, 0, 0.06) !important;
  color: #417c7d !important;
}

.st-notif-dd-body {
  flex: 1 1 auto !important;
  overflow-y: auto !important;
  max-height: 380px !important;
  padding: 8px !important;
}

.st-notif-dd-loading {
  display: none !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 8px !important;
  padding: 26px 10px !important;
  color: #64748b !important;
  font-size: 12.5px !important;
}

.st-notif-dd-loading.st-active {
  display: flex !important;
}

.st-notif-dd-empty.st-active {
  display: block !important;
}

.st-notif-item.st-notif-unread {
  background: #f0fdfa !important;
  border-left: 3px solid #417c7d !important;
}

.st-notif-item.st-notif-unread:hover {
  background: #e6f7f7 !important;
}

.st-notif-unread-dot {
  width: 7px !important;
  height: 7px !important;
  border-radius: 50% !important;
  background: #417c7d !important;
  display: inline-block !important;
  margin-left: 6px !important;
  box-shadow: 0 0 4px rgba(65, 124, 125, 0.4) !important;
}

.st-notif-spinner {
  width: 22px !important;
  height: 22px !important;
  border: 2.5px solid rgba(65, 124, 125, 0.2) !important;
  border-top-color: #417c7d !important;
  border-radius: 50% !important;
  animation: stSpin 0.7s linear infinite !important;
}

@keyframes stSpin {
  to { transform: rotate(360deg); }
}

.st-notif-dd-empty {
  text-align: center !important;
  padding: 28px 14px !important;
  color: #64748b !important;
}

.st-notif-empty-icon {
  width: 44px !important;
  height: 44px !important;
  margin: 0 auto 8px !important;
  border-radius: 50% !important;
  background: rgba(65, 124, 125, 0.08) !important;
  color: #417c7d !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

.st-notif-empty-title {
  margin: 0 0 2px !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  color: #1e293b !important;
}

.st-notif-empty-desc {
  font-size: 11.5px !important;
}

/* Comment Item in Dropdown */
.st-notif-dd-list {
  display: flex !important;
  flex-direction: column !important;
  gap: 6px !important;
}

.st-notif-item {
  display: block !important;
  padding: 10px 12px !important;
  border-radius: 8px !important;
  background: #f8fafc !important;
  border: 1px solid #e2e8f0 !important;
  cursor: pointer !important;
  transition: all 0.15s ease !important;
  text-align: left !important;
}

.st-notif-item:hover {
  background: #f1f5f9 !important;
  border-color: #417c7d !important;
  box-shadow: 0 2px 6px rgba(65, 124, 125, 0.15) !important;
  transform: translateY(-1px) !important;
}

.st-notif-item-top {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 8px !important;
  margin-bottom: 5px !important;
}

.st-notif-author-wrap {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  min-width: 0 !important;
}

.st-notif-avatar {
  width: 20px !important;
  height: 20px !important;
  border-radius: 50% !important;
  background: #417c7d !important;
  color: #ffffff !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  text-transform: uppercase !important;
  flex-shrink: 0 !important;
}

.st-notif-author-name {
  font-size: 12.5px !important;
  font-weight: 600 !important;
  color: #1e293b !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}

.st-notif-time {
  font-size: 11px !important;
  color: #64748b !important;
  white-space: nowrap !important;
  flex-shrink: 0 !important;
}

.st-notif-content {
  font-size: 12px !important;
  line-height: 1.4 !important;
  color: #334155 !important;
  margin: 0 0 6px !important;
  word-break: break-word !important;
  display: -webkit-box !important;
  -webkit-line-clamp: 2 !important;
  -webkit-box-orient: vertical !important;
  overflow: hidden !important;
}

.st-notif-item-footer {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
}

.st-notif-ticket-tag {
  display: inline-flex !important;
  align-items: center !important;
  gap: 3px !important;
  padding: 2px 6px !important;
  border-radius: 4px !important;
  background: rgba(65, 124, 125, 0.12) !important;
  color: #417c7d !important;
  font-size: 11px !important;
  font-weight: 600 !important;
}

.st-notif-ticket-type {
  font-size: 11px !important;
  color: #64748b !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}

/* Stat chips */
.st-chips {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--st-border);
  margin-bottom: 14px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.st-chips::-webkit-scrollbar {
  display: none;
}

.st-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 11px;
  font-size: 12px;
  font-weight: 500;
  color: var(--st-text-muted);
  background: var(--st-bg-subtle);
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.st-chip:hover {
  background: var(--st-border);
  color: var(--st-text);
}

.st-chip.is-active {
  background: var(--st-bg);
  border-color: #417c7d !important;
  color: #417c7d !important;
  box-shadow: 0 1px 3px rgba(65, 124, 125, 0.15);
}

.st-chip.is-active .st-chip-count {
  background: rgba(65, 124, 125, 0.12) !important;
  color: #417c7d !important;
}

.st-chip-count {
  font-weight: 600;
  color: var(--st-text);
  background: rgba(0, 0, 0, 0.05);
  padding: 1px 6px;
  border-radius: 12px;
  font-size: 11px;
}

.st-chip-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex: none;
}

.st-dot-all        { background: var(--st-text-muted); }
.st-dot-open       { background: #f6a70a; }
.st-dot-inprogress { background: #23a3d1; }
.st-dot-resolved   { background: #27ab5b; }
.st-dot-closed     { background: #2fb583; }

/* Toolbar */
.st-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}

.st-search {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 320px;
  max-width: 100%;
  height: 36px;
  padding: 0 10px;
  border: 1px solid var(--st-border);
  border-radius: var(--st-radius);
  color: var(--st-text-muted);
  background: var(--st-bg);
}

.st-search:focus-within {
  border-color: #417c7d !important;
  box-shadow: 0 0 0 2px rgba(65, 124, 125, 0.15) !important;
}

.st-search input {
  border: none;
  outline: none;
  background: transparent;
  font-size: 13px;
  width: 100%;
  height: 100%;
  color: var(--st-text);
}

.st-page-size {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--st-text-muted);
  flex-shrink: 0;
}

.st-page-size select {
  border: 1px solid var(--st-border);
  border-radius: 6px;
  padding: 4px 8px;
  font-size: 12px;
  color: var(--st-text);
  background: var(--st-bg);
  height: 32px;
  outline: none;
  cursor: pointer;
}

/* Table - Desktop View */
.st-table-wrapper {
  border: 1px solid var(--st-border);
  border-radius: var(--st-radius);
  overflow-x: auto;
  background: var(--st-bg);
  box-shadow: var(--st-shadow);
  min-height: 100px;
  position: relative;
  -webkit-overflow-scrolling: touch;
}

.st-table {
  width: 100%;
  min-width: 650px;
  border-collapse: collapse;
  font-size: 13px;
}

.st-table thead th {
  text-align: left;
  border-bottom: 2px solid rgba(65, 124, 125, 0.2) !important;
  font-weight: 500;
  font-size: 11.5px;
  color: var(--st-text-muted);
  background: var(--st-bg-subtle);
  padding: 10px 14px;
  border-bottom: 1px solid var(--st-border);
  white-space: nowrap;
}

.st-table tbody tr {
  cursor: pointer;
  transition: background 0.12s ease;
}

.st-table tbody tr:hover {
  background-color: rgba(65, 124, 125, 0.04) !important;
}

.st-table tbody tr:not(:last-child) td {
  border-bottom: 1px solid var(--st-border);
}

.st-table td {
  text-align: left;
  padding: 10px 14px;
  vertical-align: middle;
  color: var(--st-text);
}

.st-ticket-id {
  font-weight: 600;
  color: #417c7d !important;
}

.st-subject-cell {
  max-width: 240px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.st-date-cell {
  color: var(--st-text-muted);
  white-space: nowrap;
}

.st-date-main {
  display: block;
  color: var(--st-text);
}

.st-age-cell {
  color: var(--st-text-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.st-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 500;
  background: var(--st-bg-subtle);
  color: var(--st-text);
  white-space: nowrap;
}

.st-badge .st-chip-dot {
  width: 6px;
  height: 6px;
}

/* Loading / empty states */
.st-state {
  padding: 35px 20px;
  text-align: center;
  color: var(--st-text-muted);
  font-size: 13px;
}

.st-empty-title {
  margin: 0 0 4px;
  font-weight: 500;
  color: var(--st-text);
  font-size: 13.5px;
}

.st-empty-sub {
  margin: 0;
  font-size: 12px;
}

/* Pagination */
.st-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 14px;
  flex-wrap: wrap;
}

.st-pagination-info {
  font-size: 12px;
  color: var(--st-text-muted);
}

.st-pagination-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.st-page-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 11px;
  font-size: 12px;
  font-weight: 500;
  color: var(--st-text);
  background: var(--st-bg);
  border: 1px solid var(--st-border);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.st-page-btn:hover:not(:disabled) {
  background: var(--st-bg-subtle);
}

.st-page-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.st-page-indicator {
  font-size: 12px;
  color: var(--st-text-muted);
  min-width: 48px;
  text-align: center;
}

/* ==========================================================================
   Mobile View (<= 768px)
   ========================================================================== */
@media (max-width: 768px) {
  .st-app {
    padding: 0 2px;
    padding-bottom: 75px !important;
  }

  /* Sticky Top Section on Mobile */
  .st-sticky-header {
    position: sticky !important;
    top: var(--navbar-height, 48px) !important;
    z-index: 25 !important;
    background: #ffffff !important;
    padding-top: 4px !important;
    padding-bottom: 6px !important;
    border-bottom: 1px solid #e2e8f0 !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04) !important;
  }

  .st-header {
    padding: 2px 0 6px !important;
    gap: 8px !important;
    align-items: center !important;
  }

  .st-header-right {
    display: flex !important;
    flex-direction: column !important;
    align-items: flex-end !important;
    gap: 4px !important;
  }

  .st-btn-primary {
    padding: 5px 10px !important;
    font-size: 11.5px !important;
    height: 28px !important;
  }

  .st-title {
    font-size: 16px !important;
  }

  /* Toolbar: Search bar and Rows dropdown side-by-side (azu-bazu) */
  .st-toolbar {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 8px !important;
    margin-bottom: 4px !important;
    width: 100% !important;
  }

  .st-search {
    flex: 1 1 auto !important;
    width: auto !important;
    min-width: 0 !important;
    height: 36px !important;
    min-height: 36px !important;
    max-height: 36px !important;
    padding: 0 10px !important;
    border-radius: 8px !important;
    border: 1px solid #cbd5e1 !important;
    background: #ffffff !important;
  }

  .st-search:focus-within {
    border-color: #417c7d !important;
    box-shadow: 0 0 0 2px rgba(65, 124, 125, 0.18) !important;
  }

  .st-search input {
    width: 100% !important;
    height: 100% !important;
    font-size: 13px !important;
  }

  .st-page-size {
    display: inline-flex !important;
    align-items: center !important;
    gap: 5px !important;
    flex: 0 0 auto !important;
    width: auto !important;
    margin: 0 !important;
    font-size: 12px !important;
    color: var(--st-text-muted) !important;
    white-space: nowrap !important;
  }

  .st-page-size select {
    height: 36px !important;
    padding: 0 8px !important;
    border-radius: 8px !important;
    border: 1px solid #cbd5e1 !important;
    background: #ffffff !important;
    font-size: 12px !important;
    color: #1e293b !important;
    cursor: pointer !important;
  }

  .st-page-size select:focus {
    border-color: #417c7d !important;
    outline: none !important;
    box-shadow: 0 0 0 2px rgba(65, 124, 125, 0.18) !important;
  }

  .st-notif-dropdown {
    width: 320px !important;
    max-width: 88vw !important;
    right: 0 !important;
  }

  /* Hide top chips on mobile - sticky bottom nav handles filters */
  .st-chips {
    display: none !important;
  }

  /* WhatsApp Style List Container */
  .st-table thead {
    display: none !important;
  }

  .st-table-wrapper {
    background: #ffffff !important;
    border: 1px solid #e2e8f0 !important;
    border-radius: 12px !important;
    box-shadow: var(--st-shadow) !important;
    overflow: hidden !important;
    min-height: auto !important;
  }

  .st-table,
  .st-table tbody {
    display: block !important;
    width: 100% !important;
    min-width: 0 !important;
  }

  /* Each row = 1 WhatsApp Chat item */
  .st-table tbody tr {
    display: grid !important;
    grid-template-columns: 38px 1fr auto !important;
    grid-template-rows: auto auto !important;
    column-gap: 12px !important;
    row-gap: 2px !important;
    align-items: center !important;
    padding: 10px 12px !important;
    border: none !important;
    border-bottom: 1px solid #f1f5f9 !important;
    border-radius: 0 !important;
    background: #ffffff !important;
    box-shadow: none !important;
    margin: 0 !important;
    cursor: pointer !important;
